    here = os.path.dirname(os.path.abspath(__file__))
    en, uz = {}, {}
    for ru, e, u in T:
        k = re.sub(r'\s+', ' ', ru.replace('\xa0', ' ')).strip()
        en[k] = e
        uz[k] = u
    note = 'Ключ — русский текст со страницы, значение — перевод. Пересоберите сайт после правки.'
    for name, d in (('en', en), ('uz', uz)):
        json.dump({'_note': note, **d}, open(os.path.join(here, name + '.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print(len(en), 'строк')
